<?php
namespace App\Http\Controllers\Operations;use App\Http\Controllers\Controller;use App\Models\{LostFoundItem,Room};use Illuminate\Http\Request;use Illuminate\Support\Str;
class LostFoundController extends Controller{public function index(){ $p=auth()->user()->property_id;return view('operations.lost-found.index',['items'=>LostFoundItem::with('room')->where('property_id',$p)->latest()->paginate(50),'rooms'=>Room::where('property_id',$p)->orderBy('room_number')->get()]);}public function store(Request $r){$p=auth()->user()->property_id;$d=$r->validate(['room_id'=>'nullable|integer','item_name'=>'required|string|max:255','description'=>'nullable|string','found_location'=>'nullable|string','found_at'=>'required|date','storage_location'=>'nullable|string','notes'=>'nullable|string']);if(!empty($d['room_id']))Room::where('property_id',$p)->findOrFail($d['room_id']);LostFoundItem::create($d+['property_id'=>$p,'reference'=>'LF-'.now()->format('YmdHis').'-'.strtoupper(Str::random(4)),'found_by'=>auth()->id(),'status'=>'stored']);return back()->with('success','Lost and found item recorded.');}public function status(Request $r,LostFoundItem $item){abort_unless($item->property_id===auth()->user()->property_id,403);$d=$r->validate(['status'=>'required|in:stored,claimed,returned,disposed,donated','claimant_name'=>'nullable|string','claimant_phone'=>'nullable|string','notes'=>'nullable|string']);$data=$d;if($d['status']==='returned'){$data['returned_at']=now();$data['released_by']=auth()->id();}$item->update($data);return back()->with('success','Lost and found record updated.');}}
